from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Dict

from rasa.dialogue_understanding.stack.frames.dialogue_stack_frame import (
    DialogueStackFrame,
)
from rasa.shared.utils.dict_access import require_keys


@dataclass
class ChitChatStackFrame(DialogueStackFrame):
    @classmethod
    def type(cls) -> str:
        """Returns the type of the frame."""
        return "chitchat"

    @staticmethod
    def from_dict(data: Dict[str, Any]) -> ChitChatStackFrame:
        """Creates a `DialogueStackFrame` from a dictionary.

        Args:
            data: The dictionary to create the `DialogueStackFrame` from.

        Returns:
            The created `DialogueStackFrame`.
        """
        require_keys(data, "frame_id", context="Chit-chat stack frame")
        return ChitChatStackFrame(
            frame_id=data["frame_id"],
        )
